// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 bal, address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        vm.assume(bal <= address(this).balance);
        vm.deal(address(c), bal);
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        vm.prank(address(this));
        try c.withdrawAll(recipient) {} catch {}
        assertTrue(recipient.balance == beforeRecipient + beforeC);
    }
}
